pub fn linear_search(a: &Vec<i32>, e: i32) -> usize {
    // Find the first index where the element equals `e`.
    // We are guaranteed that `e` occurs at least once in `a`,
    // so `position(...).unwrap()` is safe.
    a.iter()
     .position(|&x| x == e)
     .unwrap()
}

